head.script:
scwin.onpageload = function() {
    dataList1.setJSON([{
            "col1": "1111",
            "col2": "2222",
            "col3": "Y"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "N"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": ""
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": ""
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "Y"
        }
    ]);
}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#wq_uuid_3_cell_0_2', 'key-combo', {
			combo: 'TAB'
		});
	}	
	scwin.setSimulate2 = function() {
		scwin.simulateWrapper('#wq_uuid_3_cell_1_2', 'key-combo', {
			combo: 'TAB'
		});
	}	

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_3_cell_2_2').css('background-color') == 'rgba(0, 0, 0, 0)';
	}		
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_3_cell_4_2').css('background-color') == 'rgb(252, 167, 60)';
	}		
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_3_cell_2_2 nobr').children().length == 0;
	}		
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getJq('#wq_uuid_3_cell_3_2 nobr').children().length == 0;
	}			
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_3_cell_0_2').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "400");		

		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
		WebSquare.wUnit.addCommand("pause", "400");		
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
